from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    div=None
    for i,row in enumerate(grid):
        if len(set(row))==1 and 0<i<h-1:
            div=('row',i); break
    if div is None:
        for j in range(w):
            if len({grid[i][j] for i in range(h)})==1 and 0<j<w-1:
                div=('col',j); break
    axis,k=div
    if axis=='row': a,b=grid[:k],grid[k+1:]
    else: a=[r[:k] for r in grid]; b=[r[k+1:] for r in grid]
    ca,cb=Counter(x for r in a for x in r),Counter(x for r in b for x in r)
    ma=max(ca.values()); mb=max(cb.values())
    bg_a={x for x,n in ca.items() if n==ma}; bg_b={x for x,n in cb.items() if n==mb}
    colors=(set(ca)&set(cb))-(bg_a&bg_b)
    return [[3 if a[i][j]==b[i][j] and a[i][j] in colors else 9 for j in range(len(a[0]))] for i in range(len(a))]

