def transform(grid):
    h,w=len(grid),len(grid[0]); div=None
    if h%2 and len(set(grid[h//2]))==1: div=('row',h//2)
    elif w%2 and len({grid[i][w//2] for i in range(h)})==1: div=('col',w//2)
    axis,k=div
    if axis=='row': a,b=grid[:k],grid[k+1:]
    else: a=[r[:k] for r in grid]; b=[r[k+1:] for r in grid]
    ca,cb=Counter(x for r in a for x in r),Counter(x for r in b for x in r)
    def unique_modes(c):
        m=max(c.values()); modes=[x for x,n in c.items() if n==m]
        return set(modes) if len(modes)==1 else set()
    colors=(set(ca)&set(cb))-(unique_modes(ca)&unique_modes(cb))
    return [[3 if a[i][j]==b[i][j] and a[i][j] in colors else 9 for j in range(len(a[0]))] for i in range(len(a))]
